//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:			HE_AnalogControl_Logic
//	CREATOR:		Helgevold - William Veim
// 
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	VERSION			DATE					SIGN							DESCRIPTION
//	1.0.0					2025-08-15			William Veim				Initial release
//	1.0.1					2025-08-29			William Veim				Bugfix wrong variable for limitation on feedback
//	1.0.2					2025-09-08			William Veim				Updated initialising variables
// 1.0.3					2025-12-19			William Veim				Minor bugfix ramping and added interlock return to normal as condition
//	1.0.4					2026-01-15			William Veim				Added logic for updating symbol quality state
//	1.0.5					2026-01-20			William Veim				Bugfix interlock function 
//	1.0.6					2026-02-26			William Veim				Updated scaling ramping and deadband (use scaling of output)
//	1.0.7					2026-02-26			William Veim				Updated deviation fault to use % (0-100) scaling fixed
//	1.0.8					2026-03-04			William Veim				Bugfix logic for locking feedback value to zero
//	1.1.0					2026-04-28			William Veim				Added output and logic for alarm status
//	1.2.0					2026-06-08			William Veim				Added average on feedback value
//
//================================================================================================================================
//
//		FUNCTIONALITY:
//		*	Operasjonsmodus:
//			-	OFF				Output Variable = Y0/Y1
//			-	MANUAL	Output Variable manual control from SCADA
//			-	AUTO			Input Variable copied to output scaled with Min/max
//		*	Feedback to SCADA
//		*	Fault (With delay) if the difference between opening and feedback too large.
//		*	Fault when cable break is present (Feedback = 7FFF/32767). Feedback is set to 999
//		*	Fault when feedback is not within range. Feedback is set to 999
//		*	Interlock is controlled by state control, will go to predefined output, default 0%
//
//===============================================================================================================================

(*************************************************************************
 *	INITIAL/SYSTEM VARIABELS
 *************************************************************************)
 
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);
Wrk_CurrentTime := 				TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
DayOfWeek:= 							GetDayOfWeek(In:=GetTime());
TOF_CPUStartup(In:=P_First_Run, PT:= T#5s);

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_AnalogControl.EXT_General.Remote:=											NOT Inp_LocalMode;
Ext_AnalogControl.EXT_Alarm.Sts_SupressIfOff_Visible:=					TRUE;
Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_Visible:=	NOT Cfg_FeedbackValue_Type;
Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Visible:=		NOT Cfg_OutputValue_Type;

IF NOT Ext_AnalogControl.INT_Data.Initialise THEN
	
	//General data
	Ext_AnalogControl.EXT_General.ProcessFeedback_Unit:=	'%';
	Ext_AnalogControl.EXT_General.ProcessOutput_Unit:=		'%';
	
	//Engeneering settings
	Ext_AnalogControl.EXT_Engineering.Auto_Visible:=FALSE;
	Ext_AnalogControl.EXT_Engineering.Auto_MaxOutput:=100;
	Ext_AnalogControl.EXT_Engineering.Auto_MinOutput:=0;
	Ext_AnalogControl.EXT_Engineering.Deadband:= 0.5;
	Ext_AnalogControl.EXT_Engineering.RampTime:=60;
	Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X0:=Cfg_FeedbackValue_X0;
	Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X1:=Cfg_FeedbackValue_X1;
	Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y0:=0;
	Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y1:=100;
	Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X0:=0;
	Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X1:=100;
	Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y0:=Cfg_OutputValue_Y0;
	Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y1:=Cfg_OutputValue_Y1;
	Ext_AnalogControl.EXT_Engineering.StateCfg_AllowedDeviation:=5;
	Ext_AnalogControl.EXT_Engineering.StateCfg_DeviationDelay:=30;
	Ext_AnalogControl.EXT_Engineering.Timer_RunTime:=10;
	Ext_AnalogControl.EXT_Engineering.Timer_Output:=50;
	Ext_AnalogControl.EXT_Engineering.Timer_StartTime_Hour:=12;
	Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[0]:=TRUE;
	Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[1]:=TRUE;
	Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[2]:=TRUE;
	Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[3]:=TRUE;
	Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[4]:=TRUE;
	
	//State config
	Ext_AnalogControl.EXT_Engineering.StateCfg_1.Cfg_Action:=3; //Interlock = OFF
	Ext_AnalogControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=0; //Interlock = Diagnostic
	Ext_AnalogControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Interlock = Alarm
	Ext_AnalogControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=0; //Deviation fault = Diagnostic
	Ext_AnalogControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Deviation fault = Alarm
	
	//Alarm settings
	Ext_AnalogControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_AnalogControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_AnalogControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;

	//Init complete
	Ext_AnalogControl.INT_Data.Initialise:=TRUE;
	
END_IF;

(*************************************************************************
 *	GENERATING INTERNAL VARIABLES
 *************************************************************************)

Wrk_AvailableAuto := 	Ext_AnalogControl.EXT_Operator.Mode = 2 
									AND NOT Wrk_Interlock
									AND NOT Inp_LocalMode;

(*************************************************************************
 *	MODE CONTROL
 *************************************************************************)

CASE Ext_AnalogControl.EXT_Operator.Mode OF
	
    0://OFF
			Wrk_ModeOutput := 0;
			
	1://MAN
			Wrk_ModeOutput := Ext_AnalogControl.EXT_Operator.Manual_Output;
			
	2://AUTO
	
		IF NOT TOF_CPUStartup.Q THEN //Controller startup and update controller data
			IF Ext_AnalogControl.EXT_Engineering.Auto_Visible AND Inp_Auto_Engage THEN //Auto in use
				Wrk_ModeOutput := ScaleTrans(SclIn	:=Inp_Auto_Gain,
																					X0 := 0.0, 
																					Y0 := Ext_AnalogControl.EXT_Engineering.Auto_MinOutput,
																					X1 := 100.0, 
																					Y1 := Ext_AnalogControl.EXT_Engineering.Auto_MaxOutput);
			ELSE //Auto not in use
				Wrk_ModeOutput:=0;
			END_IF;
		END_IF;
		
	3://TIMER
		
			CASE DayOfWeek OF
	
						_MON:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[0];//Active if pos 0 in array configured (TRUE)
						
						_TUE:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[1]; //Active if pos 1 in array configured (TRUE)
						
						_WED:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[2]; //Active if pos 2 in array configured (TRUE)
						
						_THU:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[3]; //Active if pos 3 in array configured (TRUE)
						
						_FRI:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[4]; //Active if pos 4 in array configured (TRUE)
						
						_SAT:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[5]; //Active if pos 5 in array configured (TRUE)
						
						_SUN:
						Wrk_TimerMode_DayActive := Ext_AnalogControl.EXT_Engineering.Timer_ActiveDays[6]; //Active if pos 6 in array configured (TRUE)
						
			END_CASE;
					
			//Start control (based on time of day)
			RE_TimerStart(Clk:=Wrk_CurrentTime = HE_INT2TOD(Hour:=Ext_AnalogControl.EXT_Engineering.Timer_StartTime_Hour, Minute:=Ext_AnalogControl.EXT_Engineering.Timer_StartTime_Minute) AND Wrk_TimerMode_DayActive);
			TON_Timer(PT:=SecToTime(Ext_AnalogControl.EXT_Engineering.Timer_RunTime));
			
			IF RE_TimerStart.Q THEN
				Wrk_TimerStarted:=TRUE;
			END_IF;
				
			IF Wrk_TimerStarted THEN
				TON_Timer.In:=TRUE;
				IF TON_Timer.Q THEN
					Wrk_TimerStarted:=FALSE;
					TON_Timer.In:=FALSE;
				END_IF;
			END_IF;
				
			IF Wrk_TimerStarted THEN	
				Wrk_ModeOutput := Ext_AnalogControl.EXT_Engineering.Timer_Output;
			ELSE
				Wrk_ModeOutput := 0.0;
			END_IF;

END_CASE;

(*************************************************************************
 *	FAULT CONTROL
 *************************************************************************)

//Fault based on deviation between feedback and output
FB_AnalogFault(ENS:=TRUE, 
					Reset:=FALSE, 
					Output:=ScaleTrans(SclIn:=Ext_AnalogControl.EXT_Operator.Actual_Output, X0:=Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X0, Y0:=0, X1:=Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X1, Y1:=100), 
					Feedback:=ScaleTrans(SclIn:=Ext_AnalogControl.EXT_Operator.Feedback, X0:=Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y0, Y0:=0, X1:=Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y1, Y1:=100), 
					MaxValue:=100, 
					AllowedDeviation:=Ext_AnalogControl.EXT_Engineering.StateCfg_AllowedDeviation, 
					Delay:= SecToTime(Ext_AnalogControl.EXT_Engineering.StateCfg_DeviationDelay));

Wrk_DeviationFault:= 				FB_AnalogFault.Fault AND NOT Inp_FeedbackValue_Fault;
Wrk_Interlock:=						Inp_Interlock AND Cfg_Interlock_InUse;

(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)

//Resets variables before state control
Ext_AnalogControl.EXT_General.Sts_Quality := 6; //Good
Wrk_ActionState:=0;

//STATE 1 - Interlock
HE_StateControl(EXT_StateData:=Ext_AnalogControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=Cfg_Interlock_InUse, 
							Inp_State:=Wrk_Interlock, 
							Inp_Desc:='Interlock', 
							Sts_Quality:=Ext_AnalogControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);

//STATE 2 - Deviation fault
HE_StateControl(EXT_StateData:=Ext_AnalogControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_DeviationFault, 
							Inp_Desc:='Deviation fault', 
							Sts_Quality:=Ext_AnalogControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//STATE 3 - From input
HE_StateControl(EXT_StateData:=Ext_AnalogControl.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Cfg_State3_InUse, 
							Inp_State:=Inp_State3_State, 
							Inp_Desc:=Inp_State3_Desc, 
							Sts_Quality:=Ext_AnalogControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//STATE 4 - From input
HE_StateControl(EXT_StateData:=Ext_AnalogControl.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Cfg_State4_InUse, 
							Inp_State:=Inp_State4_State, 
							Inp_Desc:=Inp_State4_Desc, 
							Sts_Quality:=Ext_AnalogControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//STATE 5 - From input
HE_StateControl(EXT_StateData:=Ext_AnalogControl.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=Cfg_State5_InUse, 
							Inp_State:=Inp_State5_State, 
							Inp_Desc:=Inp_State5_Desc, 
							Sts_Quality:=Ext_AnalogControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);
		
CASE Wrk_ActionState OF
	
	0://Continue operation
	Wrk_Output:= Wrk_ModeOutput;
	
	1://Freeze output
	Wrk_Output:=Wrk_Output;
	
	2://Predefined output
	Wrk_Output:=Ext_AnalogControl.EXT_Engineering.StateCfg_PreDefinedOutput;
	
	3://OFF
	Wrk_Output:=0;
	
END_CASE;				

(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_AnalogControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_AnalogControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_AnalogControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_AnalogControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_AnalogControl.EXT_General.LocationIndex,
								 Inp_AlarmSupress:=Inp_AlmSuppress, 
								 Inp_AlmSuppressDesc:=Inp_AlmSuppressDesc, 
								 Inp_Connected_Cabinet:=Cfg_ControlCabinet, 
								 Inp_Connected_Controller:=Cfg_ControllerTAG, 
								 Inp_Process_TAG:=Cfg_ProcessTAG, 
								 Inp_Process_Desc:=Ext_AnalogControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered,
								 Inp_Process_Value:= CONCAT(RealToFormatString(Ext_AnalogControl.EXT_Operator.Feedback,FALSE,FALSE,2,2), Ext_AnalogControl.EXT_General.ProcessFeedback_Unit));

(*************************************************************************
 *	OUTPUT CONTROL (Ramping and deadband)
 *************************************************************************)

//Rising edge trigger
RE_AutoEng(Clk:=						Ext_AnalogControl.EXT_Operator.Mode=2 AND Inp_Auto_Engage AND Inp_Auto_Gain>0);
FE_InterlockNormalState(Clk:=	Wrk_Interlock);
RE_MinMax_Adjusted(Clk:=			Ext_AnalogControl.EXT_Operator.Mode=2 AND (Wrk_MinOutputSample <> Ext_AnalogControl.EXT_Engineering.Auto_MinOutput OR Wrk_MaxOutputSample <> Ext_AnalogControl.EXT_Engineering.Auto_MaxOutput));
TON_RampEngage(In:=				Wrk_AutoEng OR Wrk_InterlockNormalState OR Wrk_MinOrMax_Adjusted , PT:=SecToTime(Ext_AnalogControl.EXT_Engineering.RampTime));

Wrk_MinOutputSample:=Ext_AnalogControl.EXT_Engineering.Auto_MinOutput;
Wrk_MaxOutputSample:=Ext_AnalogControl.EXT_Engineering.Auto_MaxOutput;

IF RE_AutoEng.Q AND NOT TOF_CPUStartup.Q  THEN
	Wrk_AutoEng:=TRUE;
END_IF;

IF FE_InterlockNormalState.Q AND NOT TOF_CPUStartup.Q THEN
	Wrk_InterlockNormalState:=TRUE;
END_IF;

IF RE_MinMax_Adjusted.Q AND NOT TOF_CPUStartup.Q THEN
	Wrk_MinOrMax_Adjusted:=TRUE;
END_IF;

IF TON_RampEngage.Q THEN
	Wrk_AutoEng:=FALSE;
	Wrk_InterlockNormalState:=FALSE;
	Wrk_MinOrMax_Adjusted:=FALSE;
END_IF;

//When activating AUTO mode or interlock normalizes in AUTO mode, output is ramped from previous output to AUTO output
FB_RampGain(ENS:=TRUE, 
				Inp_RampStart:=Wrk_AutoEng OR Wrk_MinOrMax_Adjusted OR Wrk_InterlockNormalState, 
				Inp_Value:=Wrk_Output, 
				Cfg_StrokeTime:=SecToTime(Ext_AnalogControl.EXT_Engineering.RampTime), 
				Cfg_Output_X0:=Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X0, 
				Cfg_Output_X1:=Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X1, 
				Cfg_Resolution:=FALSE, 
				Out_Output=>Wrk_OutputRamped);

//Deadband to reduce minimal output changes
FB_Deadband(ENS:=TRUE, 
					InputValue:=Wrk_OutputRamped, 
					PercentValue:=Ext_AnalogControl.EXT_Engineering.Deadband, 
					MinValue:=Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X0, 
					MaxValue:=Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X1, 
					OutputValue=>Wrk_OutputDeadband);

(*************************************************************************
 *	SCALING INPUT
 *************************************************************************)

FB_FeedbackAverage(ENS:=TRUE, 
									Cfg_NumberOfValues:=Wrk_NumOfValues, 
									Cfg_SamplingInterval:=Wrk_SamplingInterval, 
									Inp_Value:=Inp_FeedbackValue, 
									Out_Average=>Wrk_FeedbackValue);

IF NOT Cfg_FeedbackValue_Type THEN //Value is signal value
	
	//Feedback at X0 but fluxuating, locks to X0
	IF Inp_FeedbackValue > (Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X0 * 0.99) AND Inp_FeedbackValue < (Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X0 * 1.01) THEN
		
		Ext_AnalogControl.EXT_Operator.Feedback:= Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y0;
				
	//Normal scaling of feedback			
	ELSIF NOT Inp_FeedbackValue_Fault THEN
		
		Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal := Wrk_FeedbackValue;
		Ext_AnalogControl.EXT_Operator.Feedback := ScaleTrans(SclIn	:= Wrk_FeedbackValue,
																						X0 := Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X0, 
																						Y0 := Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y0,
																						X1 := Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X1, 
																						Y1 := Ext_AnalogControl.EXT_Engineering.Feedback_ProcessVal_Y1);
				
	//Value fault			
	ELSE
		
		Ext_AnalogControl.EXT_Operator.Feedback := Ext_AnalogControl.EXT_Operator.Feedback / Dummy;
		Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal:=Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal / Dummy;
		
	END_IF;

//Value is process value
ELSE 
	
	Ext_AnalogControl.EXT_Operator.Feedback:=Wrk_FeedbackValue;
	
END_IF;



//Limit signal value
Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X0:=LIMIT(MN:=Cfg_FeedbackValue_Min, 
																											In:=Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X0, 
																											MX:=Cfg_FeedbackValue_Max);
	
Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X1:=LIMIT(MN:=Cfg_FeedbackValue_Min, 
																										In:=Ext_AnalogControl.EXT_Engineering.Feedback_SignalVal_X1, 
																										MX:=Cfg_FeedbackValue_Max);

(*************************************************************************
 *	SCALING OUTPUT
 *************************************************************************)

IF NOT Cfg_OutputValue_Type THEN
		Ext_AnalogControl.EXT_Engineering.Output_SignalVal:=ScaleTrans(SclIn := Wrk_OutputDeadband, 
																														X0 := Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X0, 
																														Y0 := Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y0, 
																														X1 := Ext_AnalogControl.EXT_Engineering.Output_ProcessVal_X1, 
																														Y1 := Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y1);
ELSE
	Ext_AnalogControl.EXT_Engineering.Output_SignalVal:=Wrk_OutputDeadband;
END_IF;

//Limit signal value
Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y0:=LIMIT(MN:=Cfg_OutputValue_Min, 
																											In:=Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y0, 
																											MX:=Cfg_OutputValue_Max);
	
Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y1:=LIMIT(MN:=Cfg_OutputValue_Min, 
																										In:=Ext_AnalogControl.EXT_Engineering.Output_SignalVal_Y1, 
																										MX:=Cfg_OutputValue_Max);

IF NOT Cfg_OutputValue_Type THEN 
	LIMIT(MN:=Cfg_OutputValue_Min, 
			In:=Ext_AnalogControl.EXT_Engineering.Output_SignalVal, 
			MX:=Cfg_OutputValue_Max);
END_IF;

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)
 
 IF Wrk_SampleValue <> Round(Wrk_Output) THEN
	 Inc(Ext_AnalogControl.EXT_Statistics.ChangesToday);
	 Wrk_SampleValue:= Round(Wrk_Output);
 END_IF;

//Checks if new day
IF Sample_Day <> DateStruct.Day THEN
	Ext_AnalogControl.EXT_Statistics.ChangesYesterday := Ext_AnalogControl.EXT_Statistics.ChangesToday;
	Clear(Ext_AnalogControl.EXT_Statistics.ChangesToday);
	Sample_Day:=DateStruct.Day;
END_IF;
 
(*************************************************************************
 *	STRUCTURE AND OUTPUT UPDATE
 *************************************************************************)
 
 //OUTPUT
Sts_AlarmToken:=		Wrk_AlarmToken;
Sts_AlarmTriggered:=	Wrk_AlarmTriggered;
Sts_AutoAvailable := 	Wrk_AvailableAuto;
Out_Output:=				Ext_AnalogControl.EXT_Engineering.Output_SignalVal;
 
//STRUCTURE
Ext_AnalogControl.EXT_Operator.Actual_Output :=  							Wrk_OutputDeadband;
Ext_AnalogControl.EXT_General.Process_TAG:=									Cfg_ProcessTAG;
Ext_AnalogControl.EXT_General.Controlled_FromController:=			Cfg_ControllerTAG;
Ext_AnalogControl.EXT_General.Connected_ControlCabinet:=			Cfg_ControlCabinet;
Ext_AnalogControl.INT_Data.AutoAvailable:=										Wrk_AvailableAuto;
